git checkout -q -b feat/35-security-txt && mkdir -p src/pages/.well-known && cat > src/pages/.well-known/security.txt.ts <<'EOF'
import type { APIRoute } from 'astro'

import { links } from '../../lib/content'

// RFC 9116. An endpoint for the same reason as `robots.txt`: the domain and the address
// are already written down once, in `content.json`. `Expires` is required and must sit
// within a year, so it is computed from the build — every deploy pushes it forward.
// ponytail: a year with no deploy lets it lapse; pin a date in content.json if that happens.
export const GET: APIRoute = () => {
  const expires = new Date(Date.now() + 365 * 24 * 60 * 60 * 1000)
  return new Response(
    [
      `Contact: mailto:${links.email}`,
      `Expires: ${expires.toISOString()}`,
      'Preferred-Languages: es, en',
      `Canonical: ${links.domain}/.well-known/security.txt`,
      '',
    ].join('\n'),
    { headers: { 'Content-Type': 'text/plain; charset=utf-8' } },
  )
}
EOF
cat > tests/securityTxt.test.ts <<'EOF'
import { describe, expect, test } from 'bun:test'

import { GET } from '../src/pages/.well-known/security.txt'

const YEAR = 365 * 24 * 60 * 60 * 1000

describe('security.txt', () => {
  test('carries the RFC 9116 required fields, with Expires inside a year', async () => {
    const body = await (await GET({} as never)).text()
    expect(body).toContain('Contact: mailto:hi@marcosarrieta.dev')
    expect(body).toContain('Canonical: https://marcosarrieta.dev/.well-known/security.txt')

    const expires = Date.parse(body.match(/^Expires: (.+)$/m)?.[1] ?? '')
    expect(expires).toBeGreaterThan(Date.now())
    expect(expires - Date.now()).toBeLessThanOrEqual(YEAR)
  })
})
EOF
bun test tests/securityTxt.test.ts 2>&1 | tail -4 && bun run build >/dev/null 2>&1 && cat dist/.well-known/security.txt
